const now = new Date();

const trendFeeds = [
  { category: "Disconnection & Loss of Meaning", feed_url: "https://news.google.com/rss/search?q=loneliness+disconnection+community+crisis&hl=en-US&gl=US&ceid=US:en", focus: "Yoga Sutras", topic: "Yoga Sutras: The Thread of Wisdom" },
  { category: "Workplace Stress & Corporate Burnout", feed_url: "https://news.google.com/rss/search?q=workplace+stress+burnout+corporate&hl=en-US&gl=US&ceid=US:en", focus: "Pranayama & Nervous System Reset", topic: "Pranayama: The Breath of Life" },
  { category: "Sedentary Lifestyle & Physical Tension", feed_url: "https://news.google.com/rss/search?q=sedentary+lifestyle+health+posture+pain&hl=en-US&gl=US&ceid=US:en", focus: "Hatha Yoga & Somatic Alignment", topic: "Hatha Yoga: Body as Wisdom" },
  { category: "Mental Health & Overwhelm", feed_url: "https://news.google.com/rss/search?q=mental+health+anxiety+overwhelm+presence&hl=en-US&gl=US&ceid=US:en", focus: "Spiritual Philosophy & Mindfulness", topic: "Spiritual Philosophy: Awakening to the Present" },
];

// Rotates on successful publishes, not on the calendar -- re-running the
// workflow (tests, retries) no longer repeats the same topic. The counter
// only advances in a separate node placed right after a successful publish.
const staticData = $getWorkflowStaticData('global');
const idx = (staticData.topicIndex || 0) % trendFeeds.length;
const picked = trendFeeds[idx];

return [{
  json: {
    date: now.toISOString().slice(0, 10),
    category: picked.category,
    feed_url: picked.feed_url,
    focus: picked.focus,
    topic: picked.topic,
  },
}];

const items = $input.all();
const topArticles = items.slice(0, 3).map(item => ({
  title: item.json.title,
  snippet: item.json.contentSnippet || item.json.content || ''
}));

return [{
  json: {
    news_context: topArticles,
    category: $('Pick the Daily Topic').item.json.category,
    focus: $('Pick the Daily Topic').item.json.focus,
    topic: $('Pick the Daily Topic').item.json.topic
  }
}];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "news_hook": {
      "type": "string",
      "description": "One sentence, max 25 words, naming the specific development from the chosen headline: who/what/where, or the finding, or the number."
    },
    "problem": {
      "type": "string",
      "description": "What that development reveals about how people are suffering right now. Concrete and human."
    },
    "solution": {
      "type": "string",
      "description": "What the tradition teaches about this, grounded in the real tradition. Name the concept or text where there is one."
    },
    "practice": {
      "type": "string",
      "description": "One specific technique with counts or durations, doable in under five minutes, seated, with no props."
    },
    "post_type": {
      "type": "string",
      "enum": ["SINGLE_IMAGE", "CAROUSEL"],
      "description": "SINGLE_IMAGE for one shift or one breath that fits on a single frame; CAROUSEL when sequential steps are genuinely needed."
    },
    "caption": {
      "type": "string",
      "description": "130-200 words before hashtags, flowing paragraphs. Order: news specifics, honest acknowledgement, bridge to the tradition with its mechanism, the full practice with counts, warm close. No hashtags inside this text. Must name the actual news story concretely."
    },
    "hashtags": {
      "type": "array",
      "items": { "type": "string" },
      "description": "8 to 12 hashtags, each starting with '#'. Mix broad tags with ones specific to today's angle."
    },
    "slides": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "headline": {
            "type": "string",
            "description": "Big line drawn ON the image. Hard limit 6 words and 38 characters. Title Case, concrete, no quotes, no emoji, no trailing punctuation."
          },
          "sub": {
            "type": "string",
            "description": "Supporting line drawn ON the image under the headline. Hard limit 12 words and 70 characters. Must add information the headline lacks: count, mechanism, step number or duration. Sentence case, no emoji."
          },
          "body": {
            "type": "string",
            "description": "One or two sentences of editorial context. NOT drawn on the image."
          },
          "visual_prompt": {
            "type": "string",
            "description": "Subject matter only, max 30 words: people, posture, objects, arrows, diagram labels. Never mention colour, palette, art style, typeface or background."
          }
        },
        "required": ["headline", "sub", "body", "visual_prompt"]
      },
      "description": "Exactly 1 item for SINGLE_IMAGE, 3 to 5 items for CAROUSEL."
    }
  },
  "required": [
    "news_hook",
    "problem",
    "solution",
    "practice",
    "post_type",
    "caption",
    "hashtags",
    "slides"
  ]
}

parameters.jsCode:
const o = $json.output || $json;

// ---------------------------------------------------------------------------
// Post format. Set post_type_mode on the "Your Settings" node:
//   'AUTO'         -- the AI picks single image or carousel per post
//   'SINGLE_IMAGE' -- always one image
//   'CAROUSEL'     -- always a carousel
// The prompt is told the same thing, but a prompt is not a constraint, so the
// rule is enforced here as well.
// ---------------------------------------------------------------------------
const settings = $('Your Settings').first().json;
const nSlides = (o.slides || []).length;
if (settings.post_type_mode === 'SINGLE_IMAGE' || settings.post_type_mode === 'CAROUSEL') {
  o.post_type = settings.post_type_mode;
}
if (o.post_type !== 'SINGLE_IMAGE' && o.post_type !== 'CAROUSEL') {
  o.post_type = nSlides > 1 ? 'CAROUSEL' : 'SINGLE_IMAGE';
}
if (o.post_type === 'CAROUSEL' && nSlides < 2) {
  throw new Error('A carousel needs at least 2 slides but the AI returned ' + nSlides +
    '. Run again. Stopping here costs nothing; carrying on would spend image credits on a post Instagram would reject.');
}


// ---------------------------------------------------------------------------
// Brand system. Lives here, in one place, so every frame is identical.
// The LLM supplies subject matter only -- never colour, style or layout.
// ---------------------------------------------------------------------------
const BRAND = [
  'Design a 3:4 vertical Instagram poster.',
  '',
  'BACKGROUND COLOR (non-negotiable, exact, never vary): the entire background is a single flat solid fill of exactly hex #F7F4EC. No gradients, no shading, no texture, no tone variation anywhere in the background - one uniform color, edge to edge.',
  '',
  'BRAND SYSTEM (fixed, never vary): flat 2D minimalist vector illustration in an editorial infographic style. Sage green and terracotta orange accents only, with dark forest green for type. Clean geometric shapes, generous white space, no gradients, no photorealism, no 3D, no drop shadows, no paper texture.',
  '',
  'NO BORDERS, BOXES OR PLACEHOLDER SHAPES: do not draw any border, frame, card, rectangle, panel, sticky note, tag, badge or placeholder shape anywhere on the poster. The illustration and text sit directly on the flat background with nothing boxed, outlined or bordered.',
  '',
  'LAYOUT (strict):',
  '- SAFE AREA: every piece of text and every important element must sit inside the central safe area, at least 10% of the width in from the left and right edges and at least 12% of the height in from the top and bottom edges (Instagram trims roughly 3% off the top and 3% off the bottom when it displays this frame, so the top and bottom bands must hold nothing that matters). Nothing may touch or bleed off an edge. This poster is viewed as a cropped grid thumbnail, so the headline must be fully readable with room to spare on all four sides.',
  '- TOP THIRD: the headline. Bold geometric sans-serif, dark forest green, centred, on 1 or 2 lines, set large enough to read at thumbnail size.',
  '- DIRECTLY UNDER THE HEADLINE: the supporting line. Same sans-serif at a lighter weight, muted grey-green, centred, on 1 or 2 lines, clearly smaller than the headline.',
  '- LOWER TWO THIRDS: the illustration.',
   'TYPOGRAPHY: render the two text strings below exactly as written, correctly spelled, with no extra or substituted words. Do not add any other caption, label, date, handle, signature, watermark, page number or decorative filler text. Short functional labels belonging to the diagram itself (arrow labels such as INHALE / EXHALE) are allowed.',
].join('\n');

function buildPrompt(slide) {
  return BRAND +
    '\n\nHEADLINE TEXT (exact): "' + String(slide.headline || '').trim() + '"' +
    '\n\nSUPPORTING TEXT (exact): "' + String(slide.sub || '').trim() + '"' +
    '\n\nILLUSTRATION SUBJECT: ' + String(slide.visual_prompt || '').trim();
}

// Hard cap on slide count. The agent is *asked* for 3-5 slides, but a prompt is
// not a constraint, and the output-parser schema can't enforce it either (numeric
// limits there are runtime validators that hard-fail rather than degrade). Every
// extra slide is another full-size image rendered downstream, so the ceiling is
// enforced here, where it actually holds.
const MAX_SLIDES = o.post_type === 'CAROUSEL' ? 4 : 1;

const slides = (o.slides || []).slice(0, MAX_SLIDES).map((s, i) => ({
  headline: s.headline,
  sub: s.sub,
  body: s.body,
  visual_prompt: s.visual_prompt,
  slideIndex: i,
  image_prompt: buildPrompt(s),
  // Carried on every slide so the image helper workflow needs no editing.
  s3_bucket_name: settings.s3_bucket_name,
  s3_region: settings.s3_region,
}));

if (!slides.length) {
  throw new Error('AI Agent returned no slides. Raw output: ' + JSON.stringify(o).slice(0, 800));
}

// Hashtags are kept out of the caption body by the agent, then appended here so
// the prose block and the tag block stay visually separated in the IG caption.
const hashtags = (Array.isArray(o.hashtags) ? o.hashtags : [])
  .map((h) => String(h).trim())
  .filter(Boolean)
  .map((h) => (h.startsWith('#') ? h : '#' + h));

const caption = [String(o.caption || '').trim(), hashtags.join(' ')]
  .filter(Boolean)
  .join('\n\n.\n.\n.\n');

return [{
  json: {
    news_hook: o.news_hook,
    problem: o.problem,
    solution: o.solution,
    practice: o.practice,
    post_type: o.post_type,
    caption,
    hashtags,
    slides,
    // Top-level copy for the SINGLE_IMAGE branch, which reaches the renderer
    // without passing through Split Out Slides.
    image_prompt: slides[0].image_prompt,
  },
}];

// LOGO: this is a 1x1 transparent placeholder, so no logo is drawn by default.
// To add yours: make a small PNG (transparent background; bake in any opacity
// you want), convert it to base64, paste it below, and set LOGO_W / LOGO_H to
// its size in pixels. It is placed bottom-right with a margin.
const LOGO_B64 = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAC0lEQVR4nGNgAAIAAAUAAXpeqz8AAAAASUVORK5CYII=';
const LOGO_W = 1;
const LOGO_H = 1;
const LOGO_MARGIN_PCT = 0.045;

function extractImage(json) {
  const cands = json.candidates || [];
  for (const cand of cands) {
    const parts = (cand.content && cand.content.parts) || [];
    for (const p of parts) {
      const inline = p.inlineData || p.inline_data;
      if (inline && inline.data) {
        return { data: inline.data, mime: inline.mimeType || inline.mime_type || 'image/png' };
      }
    }
  }
  return null;
}

function extFor(mime) {
  if (mime.includes('jpeg') || mime.includes('jpg')) return 'jpg';
  if (mime.includes('webp')) return 'webp';
  return 'png';
}

// Read the pixel dimensions straight out of the file header so the watermark can
// be pinned to the true bottom-right corner whatever size Gemini hands back.
function imageSize(buf) {
  if (buf.length > 24 && buf[0] === 0x89 && buf[1] === 0x50) {
    return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
  }
  if (buf.length > 4 && buf[0] === 0xff && buf[1] === 0xd8) {
    let o = 2;
    while (o + 9 < buf.length) {
      if (buf[o] !== 0xff) { o++; continue; }
      const m = buf[o + 1];
      if (m === 0x01 || (m >= 0xd0 && m <= 0xd9)) { o += 2; continue; }
      const len = buf.readUInt16BE(o + 2);
      const isSOF = m >= 0xc0 && m <= 0xcf && m !== 0xc4 && m !== 0xc8 && m !== 0xcc;
      if (isSOF) return { height: buf.readUInt16BE(o + 5), width: buf.readUInt16BE(o + 7) };
      o += 2 + len;
    }
  }
  return { width: 1536, height: 2048 }; // 3:4 @ 2K fallback
}

function describeFailure(json, label) {
  const cand = (json.candidates || [])[0];
  const bits = [];
  if (cand && cand.finishReason) bits.push('finishReason=' + cand.finishReason);
  if (json.promptFeedback && json.promptFeedback.blockReason) {
    bits.push('blockReason=' + json.promptFeedback.blockReason);
  }
  const textPart = cand && cand.content && (cand.content.parts || []).find(function (p) { return p.text; });
  if (textPart) bits.push('model returned text instead of an image: ' + textPart.text.slice(0, 300));
  return 'Gemini returned no image for ' + label + '. ' + bits.join(' | ') +
    ' | raw: ' + JSON.stringify(json).slice(0, 600);
}

const logoBuf = Buffer.from(LOGO_B64, 'base64');
const out = [];
const items = $input.all();
const src = $('Normalize & Plan Slides').first().json;
const s3 = $('Your Settings').first().json;
if (!s3.s3_bucket_name || !s3.s3_region) throw new Error('Fill in s3_bucket_name and s3_region on the "Your Settings" node.');

for (let i = 0; i < items.length; i++) {
  const img = extractImage(items[i].json);
  if (!img) throw new Error(describeFailure(items[i].json, 'single image'));

  const buf = Buffer.from(img.data, 'base64');
  const dims = imageSize(buf);
  const margin = Math.round(dims.width * LOGO_MARGIN_PCT);
  const fileName = `single_${$execution.id}_${i}.${extFor(img.mime)}`;

  const bin = await this.helpers.prepareBinaryData(buf, fileName, img.mime);
  const logoBin = await this.helpers.prepareBinaryData(logoBuf, 'logo-watermark.png', 'image/png');

  out.push({
    json: {
      imageFileName: fileName,
      imageUrl: `https://${s3.s3_bucket_name}.s3.${s3.s3_region}.amazonaws.com/${fileName}`,
      caption: src.caption,
      post_type: src.post_type,
      imageWidth: dims.width,
      imageHeight: dims.height,
      logoX: Math.max(0, dims.width - LOGO_W - margin),
      logoY: Math.max(0, dims.height - LOGO_H - margin),
    },
    binary: { data: bin, logo: logoBin },
  });
}
return out;
